package org.afetatlas.offline;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Offline educational guides. Does not substitute for emergency dispatch or medical care. */
final class Guides {
  static final class Entry {
    final String category, title, body;
    Entry(String c, String t, String b) { category=c; title=t; body=b; }
  }
  private static final List<Entry> DATA;
  static {
    ArrayList<Entry> list = new ArrayList<>();
    list.add(new Entry("İlk yardım", "Acil durum değerlendirmesi", "Önce kendi güvenliğini sağla; trafik, elektrik, yangın ve duman tehlikesine yaklaşma.\n112’yi ara. Yerini, olayın türünü, yaralı sayısını ve bilinen riskleri aktar.\nBilinç ve normal solunumu kontrol et. Gereksiz hareket ettirme; yardım gelene kadar durumu izle."));
    list.add(new Entry("İlk yardım", "Şiddetli dış kanama", "112’yi ara. Eldiven varsa giy; yaraya temiz bir bezle doğrudan ve kesintisiz baskı uygula.\nBez ıslanırsa ilk bezi kaldırmadan üzerine yenisini koy. Kanama kontrol edilene kadar basıncı sürdür.\nYaşamı tehdit eden uzuv kanamasında turnike yalnızca uygun eğitim ve güncel ilk yardım talimatıyla kullanılır. Yaraya bitki, toprak veya kimyasal sürme."));
    list.add(new Entry("İlk yardım", "Burun kanaması", "Kişiyi oturt, hafifçe öne eğ. Burnun yumuşak kısmını 10–15 dakika sık.\nBaşı geriye yatırma; burnunu kuvvetle sümkürme.\nKanama durmazsa, travma varsa veya kişi kan sulandırıcı kullanıyorsa sağlık yardımı al."));
    list.add(new Entry("İlk yardım", "Bilinç kaybı", "112’yi ara. Kişiye seslen ve omuzlarından nazikçe tepki kontrol et.\nNormal nefes almıyorsa telefondaki operatörün yönlendirmesine göre kalp masajına başla.\nNormal nefes alıyorsa ve omurga yaralanması şüphesi yoksa hava yolunu koruyacak yan pozisyonu değerlendir; başından ayrılma."));
    list.add(new Entry("İlk yardım", "Kalp masajı (CPR)", "Bilinçsiz ve normal nefes almayan yetişkinde 112’yi hoparlöre al.\nEğitimli değilsen göğsün ortasına sert ve hızlı, dakikada 100–120 bası yap; göğsün tamamen geri gelmesine izin ver.\nAED varsa cihazın sesli talimatlarını izle. Çocuk ve bebeklerde teknik farklıdır; operatör yönlendirmesi önemlidir."));
    list.add(new Entry("İlk yardım", "AED kullanımı", "Cihazı aç ve sesli/görsel yönlendirmelerini takip et.\nYapışkan pedleri gösterilen yerlere yerleştir. Analiz ve şok anında kimse hastaya dokunmasın.\nCihazın talimatıyla kalp masajına devam et."));
    list.add(new Entry("İlk yardım", "Boğulma / hava yolu tıkanması", "Kişi güçlü biçimde öksürebiliyorsa öksürmesini teşvik et.\nKonuşamıyor, nefes alamıyor veya etkili öksüremiyorsa 112’yi ara; yaşına ve durumuna uygun ilk yardım manevrasını eğitim aldıysan uygula.\nBebeklerde ve hamilelerde teknik farklıdır. Bilinci kaybolursa CPR yönergelerine geç."));
    list.add(new Entry("İlk yardım", "Suda boğulma", "Kendi güvenliğini riske atma; mümkünse uzatma/atma yöntemiyle kurtar ve 112’yi ara.\nKişi sudan çıkarıldığında solunumunu değerlendir; solumuyorsa operatör yönlendirmesiyle CPR başlat.\nİyi görünse bile solunum sorunu, öksürük veya bilinç değişikliği varsa acil değerlendirme gerekir."));
    list.add(new Entry("İlk yardım", "Yanık", "Yanığı yaklaşık 20 dakika serin akan suyla soğut; hipotermiyi önle.\nYüzük, saat ve sıkı eşyaları şişmeden çıkar; yapışmış kıyafeti çekme.\nBuz, yağ, diş macunu veya bitkisel karışım sürme. Büyük, derin, kimyasal, elektrik yanıklarında 112’yi ara."));
    list.add(new Entry("İlk yardım", "Kimyasal yanık", "Önce ortamdan uzaklaş ve maddeyle doğrudan temas etme.\nKirlenmiş kıyafetleri güvenle çıkar. Kuru toz kimyasalları uygun biçimde uzaklaştırdıktan sonra genellikle bol akan suyla yıka; ürüne özgü güvenlik talimatlarını dikkate al.\nGöz, solunum yolu veya geniş alan etkilenmişse 112’yi ara."));
    list.add(new Entry("İlk yardım", "Elektrik çarpması", "Elektrik kesilmeden kişiye dokunma. Yüksek gerilim hattına yaklaşma.\nGüvenli olduğunda 112’yi ara; solunum ve bilinç kontrolü yap.\nGörünür yanık olmasa da kalp ritim bozukluğu gelişebilir; tıbbi değerlendirme gerekir."));
    list.add(new Entry("İlk yardım", "Kırık / çıkık şüphesi", "Bölgeyi bulunduğu pozisyonda destekle; yerine oturtmaya çalışma.\nKanama varsa baskı uygula, açık yarayı temiz örtüyle kapat.\nUyuşma, soğukluk, şekil bozukluğu veya şiddetli ağrıda acil yardım al."));
    list.add(new Entry("İlk yardım", "Omurga yaralanması", "Yüksekten düşme, araç kazası veya boyun-sırt travmasında gereksiz hareket ettirme.\nBaş ve boynu mevcut konumunda tut; 112’yi ara.\nYangın gibi ani tehlike dışında kişiyi taşımamaya çalış."));
    list.add(new Entry("İlk yardım", "Burkulma", "Yükü azalt, etkilenen uzvu dinlendir.\nHavluya sarılı soğuk uygulamayı kısa aralıklarla kullan; cilde doğrudan buz koyma.\nŞekil bozukluğu, üzerine basamama, uyuşma veya belirgin hassasiyet varsa sağlık kuruluşuna başvur."));
    list.add(new Entry("İlk yardım", "Baş yaralanması", "Bilinç kaybı, tekrarlayan kusma, nöbet, kötüleşen baş ağrısı, güçsüzlük veya kan sulandırıcı kullanımı acil değerlendirme gerektirir.\nKişiyi izlem altında tut; alkol verme.\n112’yi ara veya acil servise başvur; kafa travmasını hafife alma."));
    list.add(new Entry("İlk yardım", "İnme belirtileri", "Yüzde kayma, bir kolda güçsüzlük ve konuşma bozukluğu belirtilerini kontrol et.\nBaşlangıç saatini not et ve hemen 112’yi ara.\nBelirtiler geçse bile acil değerlendirme gerekir; yiyecek-içecek veya aspirin verme."));
    list.add(new Entry("İlk yardım", "Kalp krizi belirtileri", "Göğüste baskı, nefes darlığı, soğuk ter, bulantı, çeneye-kola yayılan ağrı görülebilir.\n112’yi ara; kişiyi dinlendir ve yalnız bırakma.\nİlaç konusunda operatör veya sağlık uzmanı talimatını izle; kendi başına başka kişinin ilacını verme."));
    list.add(new Entry("İlk yardım", "Şok belirtileri", "Soluk-soğuk cilt, hızlı nabız, baş dönmesi ve bilinç değişikliği görülebilir.\n112’yi ara, kanama varsa kontrol et, kişiyi sıcak tut.\nYiyecek-içecek verme; travma ve solunum durumuna göre güvenli pozisyonu koru."));
    list.add(new Entry("İlk yardım", "Anafilaksi / ağır alerji", "Nefes darlığı, dil-dudak şişmesi, yaygın döküntü ve bayılma acildir.\n112’yi ara. Kişinin reçeteli adrenalin otoenjektörü varsa talimatına uygun kullanımına yardım et.\nBelirtiler düzelse bile hastane değerlendirmesi gerekir."));
    list.add(new Entry("İlk yardım", "Astım atağı", "Kişiyi rahat nefes alabileceği oturur pozisyonda tut.\nKendi reçeteli rahatlatıcı inhalerini kullanmasına yardımcı ol.\nKonuşamama, dudaklarda morarma, bilinç değişikliği veya düzelmeme varsa 112’yi ara."));
    list.add(new Entry("İlk yardım", "Nöbet / epilepsi", "Kişiyi düşme ve keskin cisimlerden koru; başının altına yumuşak bir şey koy.\nAğzına hiçbir şey sokma, tutup bastırma; süreyi takip et.\nBeş dakikadan uzun sürerse, tekrarlarsa, yaralanma veya gebelik varsa 112’yi ara."));
    list.add(new Entry("İlk yardım", "Diyabetik acil durum", "Kişi bilinçli ve yutabiliyorsa, düşük kan şekeri düşündüren belirtilerde ölçüm ve kendi tedavi planı önemlidir.\nBilinç kapalıysa ağızdan hiçbir şey verme; 112’yi ara.\nNedeni belirsiz bilinç değişikliğinde profesyonel değerlendirme gerekir."));
    list.add(new Entry("İlk yardım", "Hipotermi", "Kişiyi rüzgâr, yağmur ve soğuktan uzaklaştır. Islak kıyafeti güvenle değiştir.\nGöğüs, boyun ve kasık gibi merkez bölgeleri yavaşça ısıt; ani aşırı ısıdan kaçın.\nBilinç bozukluğu veya ağır belirtilerde 112’yi ara."));
    list.add(new Entry("İlk yardım", "Sıcak çarpması", "Yüksek vücut ısısı, bilinç değişikliği ve bayılma hayatı tehdit eder: 112’yi ara.\nKişiyi serin yere al; kıyafetleri gevşet ve mümkün olan hızlı güvenli soğutmayı uygula.\nBilinci kapalı kişiye içecek verme."));
    list.add(new Entry("İlk yardım", "Donma", "Soğuk ve rüzgârdan koru. Donmuş bölgeyi ovuşturma; kabarcıkları patlatma.\nYeniden donma riski varsa çözündürme yapma.\nIsıtma ve yara bakımı için sağlık desteği al; geniş veya derin donmalarda acil değerlendirme gerekir."));
    list.add(new Entry("İlk yardım", "Hayvan ısırığı", "Yarayı bol akan su ve sabunla yıka, kanamayı kontrol et.\nKuduz, tetanos ve enfeksiyon açısından aynı gün tıbbi değerlendirme al.\nHayvanı yakalamaya çalışma; güvenli biçimde türünü ve olay yerini not et."));
    list.add(new Entry("İlk yardım", "Yılan ısırığı", "112’yi ara; kişiyi sakin ve hareketsiz tut.\nYüzük ve sıkı aksesuarları çıkar; ısırılan uzvu mümkün olduğunca hareket ettirme.\nKesme, emme, buz, turnike veya bitkisel tedavi uygulama; sağlık kuruluşuna ulaştır."));
    list.add(new Entry("İlk yardım", "Akrep / böcek sokması", "Bölgeyi temizle ve kişinin belirtilerini izle.\nNefes darlığı, yaygın reaksiyon, bilinç değişikliği veya özellikle çocukta ağır belirtiler varsa 112’yi ara.\nTanımlanamayan türlerde fotoğraf yalnızca güvenliyse çek; canlıyı elle yakalama."));
    list.add(new Entry("İlk yardım", "Zehirlenme", "Kimyasal, ilaç veya gaz maruziyetinde önce kendi güvenliğini sağla.\n112’yi ara; mümkünse madde ambalajını ve alınma saatini bildir.\nKusturma; bilinç kapalı kişiye ağızdan hiçbir şey verme."));
    list.add(new Entry("İlk yardım", "Gözde yabancı cisim", "Gözü ovuşturma. Küçük, serbest parçacıklar için temiz suyla nazikçe durulama düşünülebilir.\nGöze saplanmış cisme dokunma ve çıkarmaya çalışma.\nAğrı, görme kaybı veya kimyasal sıçramada acil yardım al."));
    list.add(new Entry("İlk yardım", "Diş kırılması / kopması", "Kırık parçayı veya çıkan kalıcı dişi köküne dokunmadan güvenle koru.\nKalıcı diş yerinden çıktıysa zaman önemlidir; uygun saklama sıvısı ve yeniden yerleştirme için acil diş hekimi yönlendirmesi al.\nSüt dişini yerine takmaya çalışma."));
    list.add(new Entry("İlk yardım", "İlk yardım çantası", "Tek kullanımlık eldiven, steril gazlı bez, bandaj, yara örtüsü, makas, soğuk kompres, termal örtü ve el feneri bulundur.\nKişisel ilaçları ve alerji bilgisini ekle.\nSon kullanma tarihlerini düzenli kontrol et."));
    list.add(new Entry("Afetler", "Deprem sırasında", "ÇÖK–KAPAN–TUTUN uygula; cam ve devrilebilecek eşyalardan uzak dur.\nMerdivene, balkona ve asansöre koşma.\nSarsıntı durunca güvenli çıkış ve toplanma alanı planını uygula."));
    list.add(new Entry("Afetler", "Deprem sonrasında", "Artçılara hazırlıklı ol; hasarlı binaya dönme.\nGaz kokusu, yangın veya elektrik riski varsa güvenle uzaklaş ve 112’yi ara.\nResmî duyuruları izle; gereksiz telefon trafiğini azalt."));
    list.add(new Entry("Afetler", "Enkaz altında kalma", "Ağzını ve burnunu tozdan koru; gereksiz hareketle toz kaldırma.\nTelefonla kısa mesaj veya konum paylaşımı deneyebilirsin; mümkünse düdük, duvara vurma kullan.\nBağırmak toz solumayı artırabilir; enerjini koru, kurtarma ekiplerini bekle."));
    list.add(new Entry("Afetler", "Sel ve su baskını", "Sel suyuna yaya veya araçla girme; sürüklenme ve elektrik tehlikesi vardır.\nMümkünse daha yüksek ve güvenli bölgeye çık.\nYetkililerin tahliye mesajlarını takip et."));
    list.add(new Entry("Afetler", "Orman yangını", "Duman ve alevin bulunduğu alandan uzaklaş; 112’yi ara.\nResmî tahliye yollarını kullan, yangın hattını geçmeye çalışma.\nKapalı ortamdaysan duman girişini azalt; risk varsa vakit kaybetmeden tahliye ol."));
    list.add(new Entry("Afetler", "Ev yangını", "Duman alarmı varsa ciddiye al; güvenli çıkış rotasını izle.\nDuman altında alçaktan ilerle; sıcak kapıyı açma.\nDışarı çıkınca geri dönme; 112’yi ara."));
    list.add(new Entry("Afetler", "Kar fırtınası", "Duyuruları izle, zorunlu olmadıkça yola çıkma.\nKuru giysi, battaniye, su, yiyecek ve telefon şarjı bulundur.\nAraçta mahsur kaldıysan egzoz çıkışının karla tıkanmadığını güvenli biçimde kontrol et ve karbonmonoksit riskinden korun."));
    list.add(new Entry("Afetler", "Çığ tehlikesi", "Çığ riski ilan edilmiş dik kar yamaçlarına girme.\nGüvenli noktadan 112’ye konum ve gözlemlerini bildir; ikincil çığ riskini unutma.\nEğitim ve ekipman olmadan riskli alana kurtarmaya girme."));
    list.add(new Entry("Afetler", "Heyelan / kaya düşmesi", "Çatlak, eğilen ağaç veya hareketli zemin işaretlerine dikkat et.\nTehlikeli yamaçtan uzaklaş, bölgeyi kullanma; 112 veya yerel yetkilileri bilgilendir.\nGevşek taşlı zeminde aşağıya taş düşürmemeye özen göster."));
    list.add(new Entry("Afetler", "Fırtına ve yıldırım", "Açık alan, tek başına duran ağaç, su kenarı ve metal yapılardan uzaklaş.\nSağlam kapalı bina veya uygun araç içine gir.\nGök gürültüsü duyuluyorsa dış etkinliği ertele."));
    list.add(new Entry("Afetler", "Aşırı sıcak", "Günün en sıcak saatlerinde fiziksel eforu azalt; serin ortamlarda kal.\nSuyu düzenli tüket, sıcak çarpması belirtilerini izle.\nYaşlı, çocuk ve kronik hastalığı olanların durumunu sık kontrol et."));
    list.add(new Entry("Afetler", "Nükleer serpinti", "Yetkililer aksi yönde bildirmedikçe derhal sağlam bina içine gir; bodrum veya penceresiz iç oda tercih et.\nDış kıyafeti çıkarıp ayrı tutmak bulaşı azaltabilir; açık cildi suyla yıka.\nResmî radyasyon ve tahliye talimatlarını izle. Potasyum iyodürü yalnızca yetkili sağlık açıklamasıyla kullan."));
    list.add(new Entry("Afetler", "Kimyasal sızıntı", "Kokuya bakarak maddenin güvenli olduğuna karar verme.\nResmî sığınma/tahliye talimatlarını izle, kapalı alana geç; gerekiyorsa pencere ve havalandırmayı kapat.\nBelirti veya maruziyet varsa 112’yi ara ve maddenin adını bildir."));
    list.add(new Entry("Afetler", "Biyolojik salgın", "Resmî sağlık kurumunun hastalığa özel önerilerini takip et.\nEl hijyeni, uygun havalandırma ve belirtili kişilerin teması azaltması temel önlemlerdir.\nAşı, test ve koruyucu ekipman önerileri etkenin türüne göre değişir."));
    list.add(new Entry("Afetler", "Karbonmonoksit", "Baş ağrısı, bulantı, halsizlik ve bilinç değişikliği görülebilir; gaz renksiz ve kokusuzdur.\nKendi güvenliğini riske atmadan temiz havaya çık ve 112’yi ara.\nŞüpheli ortama geri dönme; uygun CO dedektörü kullan."));
    list.add(new Entry("Afetler", "Tahliye planı", "Evden iki çıkış alternatifi ve dışarıda aile buluşma noktası belirle.\nEngelli, çocuk ve evcil hayvanların ihtiyaçlarını plana kat.\nBelgeleri, ilaçları ve acil çantayı erişilebilir yerde tut."));
    list.add(new Entry("Afetler", "Aile iletişim planı", "Birincil ve alternatif buluşma noktası belirle.\nHerkesin bildiği bir şehir dışı irtibat kişisi seç.\nSMS ve mesajlaşma uygulamaları bazen sesli aramadan daha verimli olabilir; iletişim kopmasına hazırlık yap."));
    list.add(new Entry("Afetler", "Toplanma alanları", "Yaşadığın yerdeki resmî AFAD toplanma alanını önceden öğren.\nGidiş rotasını ve alternatifini değerlendir.\nHarita üzerinde rastgele yeşil alanı resmî toplanma alanı sanma."));
    list.add(new Entry("Afetler", "Deprem güvenli ev hazırlığı", "Dolap, raf ve ağır eşyaları uygun biçimde sabitle.\nYatak üstündeki düşebilecek cisimleri kaldır.\nGaz, su ve elektrik kesicilerinin yerini öğren; yapı güvenliği için uzman değerlendirmesini esas al."));
    list.add(new Entry("Afetler", "Acil durum çantası", "Kişi başına uygun su, dayanıklı gıda, fener, pil, düdük, battaniye, hijyen malzemesi, nakit ve belge kopyası ayır.\nİlaç ve bebek ihtiyaçlarını özelleştir.\nÇantayı mevsime ve aile durumuna göre güncelle."));
    list.add(new Entry("Su ve gıda", "İçilebilir su önceliği", "Öncelik ambalajlı güvenilir su veya güvenli şebeke suyudur.\nKaynağı belirsiz suyu doğrudan içme.\nKaynatma mikroorganizmaları azaltabilir; kimyasal, ağır metal ve radyoaktif kirleticileri gidermeyebilir."));
    list.add(new Entry("Su ve gıda", "Su kaynatma", "Şüpheli fakat kimyasal olarak kirli olmadığı bilinen suyu mümkünse önce berraklaştır.\nSu kaynadıktan sonra en az bir dakika kaynat; yüksek rakım için süre uzayabilir.\nTemiz, kapaklı kapta sakla."));
    list.add(new Entry("Su ve gıda", "Su filtreleme sınırları", "Bez veya basit mekanik filtreler bulanıklığı ve parçacıkları azaltabilir ancak tek başına tüm mikropları gidermez.\nFiltre ürününün virüs, bakteri ve protozoa performansını üretici bilgisine göre değerlendir.\nKimyasal kirlenmiş suyu basit filtre veya kaynatmayla güvenli sayma."));
    list.add(new Entry("Su ve gıda", "Su depolama", "İçme suyunu gıdaya uygun, temiz ve sızdırmaz kaplarda sakla.\nÜzerine tarih ve kaynağını yaz.\nKirli kapla su alma, depoyu aşırı sıcakta bırakma."));
    list.add(new Entry("Su ve gıda", "Susuzluk belirtileri", "Koyu idrar, aşırı susama, baş dönmesi ve halsizlik sıvı kaybı göstergesi olabilir.\nGüvenilir içme suyu ve uygun koşullarda elektrolit desteği kullan.\nBilinç bozukluğu, uzun süren kusma veya belirgin halsizlikte tıbbi yardım al."));
    list.add(new Entry("Su ve gıda", "Gıda saklama", "Soğuk zinciri kırılmış et, süt ve pişmiş gıdalar riskli olabilir.\nGıdayı haşere, nem ve sıcaktan koru.\nBozulmuş görünümlü ya da kokulu gıdayı tatma; koku her riski göstermez."));
    list.add(new Entry("Su ve gıda", "Konserve güvenliği", "Şişmiş, paslı, sızıntılı veya hasarlı konserveyi açıp tatma.\nEv konservesinde botulizm riski uygun işlem yapılmadığında artar.\nŞüpheli konserveyi tüketme."));
    list.add(new Entry("Su ve gıda", "Gıda zehirlenmesi", "Kusma ve ishalde güvenilir sıvı alımı önemlidir.\nKanlı ishal, yüksek ateş, bilinç değişikliği veya ağır susuzlukta sağlık yardımına başvur.\nÇocuk, yaşlı ve gebelerde değerlendirme eşiği daha düşüktür."));
    list.add(new Entry("Su ve gıda", "Güvenli pişirme", "Çiğ et ve hazır gıdaların yüzeylerini ayır.\nGıdayı içinin de yeterince pişmesini sağlayacak şekilde hazırla.\nEldiven kullanmak el yıkamanın yerini almaz."));
    list.add(new Entry("Su ve gıda", "El hijyeni", "Tuvalet, yara bakımı ve gıda hazırlığı öncesi/sonrası ellerini su ve sabunla yıka.\nSu yoksa eller görünür biçimde kirli değilken uygun alkol bazlı el antiseptiği kullanılabilir.\nKimyasalları ve temizlik ürünlerini birbirine karıştırma."));
    list.add(new Entry("Su ve gıda", "Atık ve tuvalet hijyeni", "İnsan atığını su kaynaklarından ve yaşam alanlarından uzak, yerel sağlık önerilerine uygun yönet.\nÇöpleri kapalı biriktir; haşere girişini azalt.\nGeçici tuvalet kurulumu için yerel çevre ve sağlık kurallarını izle."));
    list.add(new Entry("Su ve gıda", "Su kaynaklarını koruma", "Sabun, yakıt ve atığı akarsulara dökme.\nİçme suyu alma noktasını temizlik ve çamaşır alanından ayır.\nYağmur ve taşkın sonrası yüzey suyunun kontaminasyon riski artabilir."));
    list.add(new Entry("Su ve gıda", "Ateşsiz gıda seçenekleri", "Güvenle saklanan hazır gıda ve aç-kapa ambalajları önceliklendir.\nIsıl işlem gerektiren çiğ ürünleri zorunlu olmadıkça tüketme.\nDüzenli beslenmede sıvı, enerji ve özel diyet gereksinimlerini göz önüne al."));
    list.add(new Entry("Su ve gıda", "Bebek beslenmesi", "Bebek maması hazırlarken güvenilir su ve hijyen özellikle önemlidir.\nEmzirme mümkünse sürdürülmesi için destek sağla.\nFormül mama talimatlarını ve saklama sürelerini takip et."));
    list.add(new Entry("Su ve gıda", "Gıda alerjileri", "Alerjenleri ürün etiketinden kontrol et; çapraz temas riskine dikkat et.\nKişisel acil eylem planı ve reçeteli ilaçları erişilebilir tut.\nAnafilaksi belirtilerinde 112’yi ara."));
    list.add(new Entry("Doğada kalma", "İlk 10 dakika", "Paniğe kapılmadan dur ve riskleri değerlendir.\nKonumunu belirlemeye çalış; kaybolduysan rastgele uzaklaşma.\nBarınak, hava koşulları, su ve iletişim önceliklerini değerlendir."));
    list.add(new Entry("Doğada kalma", "Kaybolunca yön bulma", "Harita ve pusula varsa birlikte kullan.\nTelefon GPS koordinatını kaydedebilir ancak pil ve sinyal sınırlıdır.\nGüvenli bir noktada kalıp yardım çağırmak, bilinmeyen arazide yürümekten daha güvenli olabilir."));
    list.add(new Entry("Doğada kalma", "Pusula temel kullanımı", "Pusulayı düz tut; manyetik alanı etkileyebilecek metalleri uzaklaştır.\nHaritadaki kuzey ve manyetik kuzey farkını değerlendir.\nArazide yürürken tek bir uzaktaki güvenilir referansa bakarak yönü koru."));
    list.add(new Entry("Doğada kalma", "GPS ile konum paylaşma", "Koordinatları ondalık derece olarak not et; örnek biçim: 39.0000, 35.0000.\n112’ye mümkünse koordinat, yakın yer adı ve ulaşım bilgisi aktar.\nTelefonun konum hassasiyeti kapalı alan, kanyon ve zayıf uydu görüşünde düşebilir."));
    list.add(new Entry("Doğada kalma", "Güvenli barınak seçimi", "Sel yatağı, kaya düşme hattı, kuru dere ve çığ riski altındaki yerlerden uzak dur.\nRüzgârdan korunan, stabil zemin seç.\nTehlikeli bitkiler, hayvan yuvaları ve geçiş yollarına dikkat et."));
    list.add(new Entry("Doğada kalma", "Geceleme planı", "Hava kararmadan güvenli konum ve barınma düzenini tamamla.\nIslak kıyafetleri değiştir, yerden ısı kaybını azaltacak yalıtım kullan.\nAteş yakacaksan yangın riski ve yerel yasakları değerlendir."));
    list.add(new Entry("Doğada kalma", "Vücut ısısını koruma", "Katmanlı giyin; ıslak kumaşı vücuttan uzaklaştır.\nZeminle temas ısı kaybını artırır; yalıtımlı altlık kullan.\nAşırı terlemeyi azaltmak için efor ve kıyafetleri ayarla."));
    list.add(new Entry("Doğada kalma", "Güneşten korunma", "Şapka, gölge, uygun kıyafet ve güneş koruması kullan.\nÖğle saatlerinde aşırı efordan kaçın.\nBaş dönmesi ve bilinç değişikliği ısı kaynaklı acil durum işareti olabilir."));
    list.add(new Entry("Doğada kalma", "Düğüm ve bağlantı güvenliği", "Düğüm seçimi yük, halat türü ve kullanım amacına bağlıdır.\nEmniyet, tırmanış ve kurtarma uygulamaları yalnızca uygun eğitimli kişi ve sertifikalı ekipmanla yapılmalıdır.\nDüğümleri yük vermeden önce kontrol et."));
    list.add(new Entry("Doğada kalma", "Ateş güvenliği", "Yerel yangın yasağı varsa ateş yakma.\nYalnızca uygun, korunaklı alanda ve yeterli söndürme suyu varsa ateş değerlendir.\nAteşi tamamen söndürmeden alandan ayrılma; çadır içinde veya kapalı yerde yakma."));
    list.add(new Entry("Doğada kalma", "Kamp ocağı güvenliği", "Kapalı çadır, araç ve odada yakıtlı ocak kullanma; karbonmonoksit riski yüksektir.\nYakıt sızıntılarını kontrol et; cihazı düz ve güvenli zeminde kullan.\nSıcak yüzeylerden çocukları ve yanıcı malzemeleri uzak tut."));
    list.add(new Entry("Doğada kalma", "Doğada su bulma", "Yağmur suyu ve akan kaynaklar dahi mikroorganizma veya kimyasal kirletici taşıyabilir.\nSuyu güvenilir arıtma yönteminden geçir; tuzlu suyu doğrudan içme.\nBilinmeyen su için yalnızca berrak görünmesine güvenme."));
    list.add(new Entry("Doğada kalma", "Nehir geçişi", "Hızlı akan veya derinliği belirsiz suya girme.\nAlternatif köprü ve güvenli geçiş ara.\nSel sonrası su geçişinden tamamen kaçın; küçük akışlar dahi insanı sürükleyebilir."));
    list.add(new Entry("Doğada kalma", "Dağ ve yamaç güvenliği", "Hava, eğim, düşen taş, gevşek zemin ve kar durumunu değerlendir.\nPlanını birine bildir ve geri dönüş saati belirle.\nEğitim ve güvenlik ekipmanı olmadan teknik rota deneme."));
    list.add(new Entry("Doğada kalma", "Gece yürüyüşü", "Zorunlu olmadıkça belirsiz arazide gece hareket etme.\nBaş feneri, yedek pil ve geri dönüş planı hazırla.\nKaybolursan uçurum, dere yatağı ve araç yoluna kontrolsüz ilerleme."));
    list.add(new Entry("Doğada kalma", "Yabani hayvanlarla karşılaşma", "Hayvana yaklaşma, besleme ve kaçış yolunu kapatma.\nYiyecekleri kapalı sakla.\nBüyük veya saldırgan hayvanda mesafeyi koru; bulunduğun bölgenin resmî yaban hayatı önerilerini izle."));
    list.add(new Entry("Doğada kalma", "Kene kontrolü", "Ot ve çalılık alanlardan sonra cilt ve kıyafeti kontrol et.\nTutunmuş keneyi uygun ince uçlu cımbızla, ezmeden ve deriye yakın yerden çıkar; çıkaramıyorsan sağlık kuruluşuna başvur.\nYağ, ateş veya kimyasal dökme; ateş veya döküntü gelişirse hekime başvur."));
    list.add(new Entry("Doğada kalma", "Sis ve düşük görüş", "Görüş azalınca hızını düşür veya güvenli yerde bekle.\nGPS/harita ile doğrulama yap; tek referansla tehlikeli yamaçlara ilerleme.\nSinyal, pil ve hava durumunu takip et."));
    list.add(new Entry("Doğada kalma", "Kıyıda güvenlik", "Gelgit, dalga ve akıntı koşullarını değerlendir.\nKayalık kıyıda kaygan yüzey ve yükselen dalga riskine dikkat et.\nBoğulan kişiyi kurtarmak için kontrolsüz suya girme."));
    list.add(new Entry("Doğada kalma", "Aciliyet sıralaması", "İlk öncelik hayatı tehdit eden tehlikelerden uzaklaşmak ve ciddi yaralanmaları yönetmektir.\nSonra hava koşullarına uygun barınak, iletişim ve güvenilir suyu planla.\nYiyecek temini için riskli bitki veya hayvan denemeleri yapma."));
    list.add(new Entry("Bitki ve doğa", "Yabani bitki tanımanın sınırları", "Fotoğraf veya tek özellik üzerinden yenilebilirlik kararı verme; zehirli benzer türler olabilir.\nKesin teşhis yapılmadan bitki yeme veya yaraya sürme.\nBitki adı, yöre ve mevsim tek başına güvenlik kanıtı değildir."));
    list.add(new Entry("Bitki ve doğa", "Mantar zehirlenmesi", "Yabani mantarlar güvenli olarak yalnızca uzman tanısıyla tüketilebilir.\nZehirli türler pişirmekle veya kaynatmakla güvenli hâle gelmeyebilir.\nŞüpheli tüketim ve belirtilerde gecikmeden 112’yi ara; mümkünse örneği güvenle sakla."));
    list.add(new Entry("Bitki ve doğa", "Zakkum", "Zakkumun yaprak, çiçek ve diğer kısımları zehirli olabilir.\nÇay, merhem veya gıda olarak kullanma.\nYutma şüphesinde 112’yi ara; kusturma."));
    list.add(new Entry("Bitki ve doğa", "Baldıran", "Baldıran çok zehirli bir bitkidir ve bazı yenilebilir bitkilere benzeyebilir.\nYabani havuç, maydanoz veya benzer şemsiyegilleri yalnızca görsel benzerlikle toplamaya çalışma.\nŞüpheli tüketimde hemen acil yardım al."));
    list.add(new Entry("Bitki ve doğa", "Güzelavrat otu", "Güzelavrat otunun meyveleri ve diğer kısımları ciddi zehirlenmeye neden olabilir.\nMeyvelerini tüketme; çocuklardan uzak tut.\nTemas veya yutma sonrası belirti gelişirse acil yardım al."));
    list.add(new Entry("Bitki ve doğa", "Porsuk ağacı", "Porsuk ağacının birçok kısmı çok zehirlidir; ciddi kalp ritim bozukluğu yapabilir.\nTohum ve yapraklarını tüketme.\nŞüpheli maruziyette 112’yi ara."));
    list.add(new Entry("Bitki ve doğa", "Yabani sarımsak benzerleri", "Yabani sarımsak benzeri yapraklar bazı zehirli bitkilerle karışabilir.\nKoku tek başına kesin tanı değildir.\nUzman tarafından doğrulanmayan yabani yaprakları yeme."));
    list.add(new Entry("Bitki ve doğa", "Isırgan otu", "Isırganın tüyleri ciltte yanma ve kaşıntı yapabilir.\nTür ve maruziyet güvenliği bilinmeden gıda veya tıbbi amaçla kullanma.\nAlerji belirtisinde sağlık desteği al."));
    list.add(new Entry("Bitki ve doğa", "Kuşburnu", "Kuşburnu meyveleri bazı bölgelerde gıda olarak kullanılır; yabani meyveyi yalnızca kesin tür tanısıyla tüket.\nYol kenarı kirliliği ve pestisit riskini değerlendir.\nŞifalı tedavi yerine kullanma."));
    list.add(new Entry("Bitki ve doğa", "Kekik ve benzerleri", "Aromatik kokulu bitkiler birbirine benzeyebilir; kesin tanı olmadan toplama.\nUçucu yağlar yoğun ve tahriş edicidir; cilde saf sürme ve ağızdan tedavi amaçlı alma.\nÇocuklar ve hamileler için ek riskler bulunabilir."));
    list.add(new Entry("Bitki ve doğa", "Yara üzerine bitki uygulamaları", "Ciddi kanamayı durdurmak için bitki, kahve, un veya toprak kullanma.\nTemiz bezle doğrudan bası uygula ve 112’yi ara.\nYabani bitkiler enfeksiyon, alerji ve yabancı cisim riski yaratabilir."));
    list.add(new Entry("Bitki ve doğa", "Bitki zehirlenmesine yaklaşım", "Şüpheli bitki yenmişse kusturma veya ev yapımı panzehir verme.\n112’yi ara ve mümkünse bitkinin fotoğrafını, tüketim zamanını, belirtileri kaydet.\nSağlık ekibi istemedikçe kişiye yiyecek-içecek verme."));
    list.add(new Entry("Bitki ve doğa", "İçme suyunda alg / çiçeklenme", "Göl veya durgun suda renk değişimi, köpük veya yoğun alg varsa temastan ve içmekten kaçın.\nKaynatmak bazı alg toksinlerini güvenli hâle getirmez.\nGüvenilir alternatif su kaynağı kullan."));
    list.add(new Entry("Bitki ve doğa", "Doğal tedavilerin sınırı", "Şifalı bitkiler ilaçlarla etkileşebilir ve dozları standardize olmayabilir.\nAcil yaralanma, zehirlenme ve enfeksiyon için bitkisel çözüme güvenme.\nÖzellikle çocuk, gebe ve kronik hastalıkta sağlık uzmanına danış."));
    list.add(new Entry("İletişim ve hazırlık", "112 ararken ne söylemeli", "Konum, olay türü, yaralı sayısı, bilinç-solunum durumu ve erişim yolunu net söyle.\nTelefonu kapatma; operatörün sorularını yanıtla.\nRiskli bölgeye girme; mümkünse birini ekipleri karşılamaya yönlendir."));
    list.add(new Entry("İletişim ve hazırlık", "Acil durumda telefon pili", "Ekran parlaklığını düşür; gereksiz uygulamaları kapat.\nHücresel kapsama yoksa güvenli yüksek nokta veya açık alanda sinyal dene.\nTelefonu soğuktan koru; güç bankasını önceden şarj et."));
    list.add(new Entry("İletişim ve hazırlık", "Konum yazma biçimi", "Koordinatları 'enlem, boylam' sırasıyla ve ondalık derecelerle yaz.\nYakın il/ilçe, yol, köprü veya belirgin arazi işaretini ekle.\nHarita konumu kişiyi gösteriyor olsa bile yer bilgisini sözlü teyit et."));
    list.add(new Entry("İletişim ve hazırlık", "Afet haberleri / dezenformasyon", "Resmî kurumlardan ve güvenilir kaynaklardan doğrulamadan kritik uyarı paylaşma.\nTarih, bölge ve güncellemeleri kontrol et.\nElektrik ve iletişim kesintisine karşı radyo veya alternatif kaynak planla."));
    list.add(new Entry("İletişim ve hazırlık", "Evde hazır bulundurma", "Her birey için kişisel ihtiyaç listesi oluştur.\nSu, ışık, hijyen, ilaç, battaniye ve gerekli ekipmanı düzenli yenile.\nHer aile üyesi acil çantanın ve kesicilerin yerini bilsin."));
    list.add(new Entry("İletişim ve hazırlık", "Engelli ve yaşlılar için plan", "İlaç, tıbbi cihaz elektriği, mobilite desteği ve erişilebilir tahliye yolunu önceden planla.\nGüvenilir komşu/akraba irtibatı belirle.\nYazılı acil durum kartı ve cihaz yedeklerini erişilebilir tut."));
    list.add(new Entry("İletişim ve hazırlık", "Evcil hayvan afet planı", "Kimlik ve aşı bilgilerini, tasma/taşıma kutusunu hazır bulundur.\nHayvanı terk etmeden güvenli tahliye planı yap.\nHayvanın ilaç ve su ihtiyacını çantaya ekle."));
    list.add(new Entry("İletişim ve hazırlık", "Araç acil çantası", "Su, yedek kıyafet, battaniye, reflektör, ışık ve şarj ekipmanı bulundur.\nMevsime göre zincir veya uygun lastik gereksinimlerini değerlendir.\nAraçta yakıtlı cihaz kullanma; karbonmonoksit riskini unutma."));
    list.add(new Entry("İletişim ve hazırlık", "Aile tatbikatı", "Çıkış, buluşma noktası ve 112 iletişim provası yap.\nÇocuklara yaşlarına uygun güvenli davranışları öğret.\nTatbikat sonunda eksikleri ve erişim engellerini düzelt."));
    list.add(new Entry("İletişim ve hazırlık", "Belgeler ve mahremiyet", "Kimlik, reçete ve kritik iletişim bilgilerini güvenli şekilde yedekle.\nDijital kopyaları güçlü kilit ve mümkünse şifreli depolamayla koru.\nAcil iletişim kartını gereksiz kişisel veri içermeden hazırla."));
    list.add(new Entry("İletişim ve hazırlık", "Çevrimdışı harita kullanımı", "Haritayı önceden indir, telefon uçak modundayken açılışını test et.\nOffline harita görüntüsü her zaman yönlendirme veya güncel yol kapanışı bilgisi sağlamaz.\nÖnemli rotalar için kâğıt harita ve pusula da bulundur."));
    list.add(new Entry("İletişim ve hazırlık", "AFAD ve resmî kaynaklar", "Türkiye’de afet uyarısı, toplanma alanı ve tahliye için AFAD ve yerel yetkili kurumların güncel talimatlarını izle.\nUygulamanın çevrimdışı içeriği güncel resmî uyarıların yerine geçmez.\nHayati durumda 112’yi ara."));
    DATA = Collections.unmodifiableList(list);
  }
  static List<Entry> all() { return DATA; }
  static int count() { return DATA.size(); }
}